// overview.get: Read the cluster overview of a connection
// Generated by `pnpm nx g @app/generators:action overview.get`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import { FreshnessSchema } from './explorer-types.ts';

/** The most nodes one answer names. */
export const OVERVIEW_NODES_MAX = 100;

const count = z.number().int().nonnegative();

export const OverviewGetInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
});

export const OverviewGetOutputSchema = z.strictObject({
  product: z.string(),
  version: z.string().optional(),
  clusterName: z.string().optional(),
  totals: z.strictObject({
    queues: count.optional(),
    exchanges: count.optional(),
    connections: count.optional(),
    /** Absent when the broker does not report them (statistics off). */
    channels: count.optional(),
    consumers: count.optional(),
    /** The broker's own message totals when it reports them, else the sum over the queue sweep. */
    messages: z
      .strictObject({
        total: count,
        ready: count,
        unacknowledged: count,
        source: z.enum(['broker-overview', 'queue-sweep']),
        /** Epoch ms the totals describe: the answer's time, or the sweep that was summed. */
        asOf: count,
        /** False when the sweep behind the sum is partial, capped, or a queue did not report a count. */
        complete: z.boolean(),
      })
      .optional(),
  }),
  /** Available only when the broker reports rates; never a zero the broker did not send. */
  rates: z.discriminatedUnion('state', [
    z.strictObject({
      state: z.literal('available'),
      source: z.literal('broker-overview'),
      publishPerSec: z.number().optional(),
      deliverPerSec: z.number().optional(),
    }),
    z.strictObject({
      state: z.literal('unavailable'),
      reason: z.enum(['statistics-off', 'not-reported']),
    }),
  ]),
  nodes: z
    .array(
      z.strictObject({
        name: z.string(),
        running: z.boolean(),
        beingDrained: z.boolean().optional(),
      }),
    )
    .max(OVERVIEW_NODES_MAX),
  /** `unknown` whenever the state could not be read or attributed: never reported as `none`. */
  alarms: z.discriminatedUnion('state', [
    z.strictObject({ state: z.literal('none') }),
    z.strictObject({
      state: z.literal('active'),
      active: z
        .array(
          z.strictObject({
            node: z.string(),
            resource: z.enum(['memory', 'disk', 'other']),
          }),
        )
        .min(1)
        .max(OVERVIEW_NODES_MAX * 2),
    }),
    z.strictObject({
      state: z.literal('unknown'),
      reason: z.string().max(200),
    }),
  ]),
  /** The state of the inventory index the sweep-derived totals come from. */
  freshness: FreshnessSchema,
});

export const overviewGet = defineAction({
  id: 'overview.get',
  kind: 'query',
  summary: 'Read the cluster overview of a connection',
  input: OverviewGetInputSchema,
  output: OverviewGetOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'GET', path: '/connections/{cid}/overview' },
  since: '1.0',
});
